import{_ as r,o as t,c as e,a3 as n}from"./chunks/framework.D81Tvp8W.js";const c=JSON.parse('{"title":"NLP 学习路线","description":"","frontmatter":{"title":"NLP 学习路线","date":"2025-09-02T00:00:00.000Z","categories":["ai","NLP"],"tags":["AI","NLP"]},"headers":[],"relativePath":"ai/NLP/5.学习路线.md","filePath":"ai/NLP/5.学习路线.md","lastUpdated":1786872962000}'),l={name:"ai/NLP/5.学习路线.md"};function i(o,a,s,h,d,g){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="🗺️-nlp-学习路线" tabindex="-1">🗺️ NLP 学习路线 <a class="header-anchor" href="#🗺️-nlp-学习路线" aria-label="Permalink to &quot;🗺️ NLP 学习路线&quot;">​</a></h1><p>NLP 内容多、演进快，容易迷失方向。本文给出一条从零到实战的可行路径，并标注本站配套资源。</p><hr><h2 id="🪜-总路线图" tabindex="-1">🪜 总路线图 <a class="header-anchor" href="#🪜-总路线图" aria-label="Permalink to &quot;🪜 总路线图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>①语言基础 ─→ ②词向量 ─→ ③序列模型 ─→ ④注意力/Transformer</span></span>
<span class="line"><span>                                              ↓</span></span>
<span class="line"><span>                                   ⑤预训练模型（BERT/GPT）</span></span>
<span class="line"><span>                                              ↓</span></span>
<span class="line"><span>                                   ⑥实战框架 + 大模型应用</span></span></code></pre></div><hr><h2 id="📚-分阶段学习" tabindex="-1">📚 分阶段学习 <a class="header-anchor" href="#📚-分阶段学习" aria-label="Permalink to &quot;📚 分阶段学习&quot;">​</a></h2><h3 id="阶段-1-语言基础-选学" tabindex="-1">阶段 1：语言基础（选学） <a class="header-anchor" href="#阶段-1-语言基础-选学" aria-label="Permalink to &quot;阶段 1：语言基础（选学）&quot;">​</a></h3><p>了解 NLP 面对的原始问题，不深究传统算法也可。</p><ul><li>分词、词性、句法（大致了解概念）</li><li>语料与评价指标（BLEU、F1、困惑度）</li></ul><h3 id="阶段-2-词向量" tabindex="-1">阶段 2：词向量 <a class="header-anchor" href="#阶段-2-词向量" aria-label="Permalink to &quot;阶段 2：词向量&quot;">​</a></h3><p>理解&quot;词如何变成向量&quot;。</p><ul><li>Word2Vec（CBOW / Skip-gram）</li><li>GloVe</li><li><strong>本站配套</strong>：<a href="./../DeepLearning/自然语言处理：预训练/">深度学习 → 自然语言处理：预训练</a> 的 word2vec 章节</li></ul><h3 id="阶段-3-序列模型" tabindex="-1">阶段 3：序列模型 <a class="header-anchor" href="#阶段-3-序列模型" aria-label="Permalink to &quot;阶段 3：序列模型&quot;">​</a></h3><p>理解序列如何被建模。</p><ul><li>RNN、LSTM、GRU</li><li>Seq2Seq（编码器-解码器）</li><li><strong>本站配套</strong>：<a href="./../DeepLearning/循环神经网络/">深度学习 → 循环神经网络</a></li></ul><h3 id="阶段-4-注意力与-transformer-重点" tabindex="-1">阶段 4：注意力与 Transformer（重点） <a class="header-anchor" href="#阶段-4-注意力与-transformer-重点" aria-label="Permalink to &quot;阶段 4：注意力与 Transformer（重点）&quot;">​</a></h3><p>这是现代 NLP 的基石，务必学透。</p><ul><li>注意力机制、多头注意力</li><li>Transformer 架构</li><li><strong>本站配套</strong>：<a href="./../DeepLearning/注意力机制/">深度学习 → 注意力机制</a></li></ul><h3 id="阶段-5-预训练模型" tabindex="-1">阶段 5：预训练模型 <a class="header-anchor" href="#阶段-5-预训练模型" aria-label="Permalink to &quot;阶段 5：预训练模型&quot;">​</a></h3><p>理解 BERT 与 GPT 两大流派。</p><ul><li>BERT：掩码语言模型（编码器）</li><li>GPT：自回归语言模型（解码器）</li><li><strong>本站配套</strong>：<a href="./../DeepLearning/自然语言处理：预训练/">深度学习 → NLP 预训练</a></li></ul><h3 id="阶段-6-实战与进阶" tabindex="-1">阶段 6：实战与进阶 <a class="header-anchor" href="#阶段-6-实战与进阶" aria-label="Permalink to &quot;阶段 6：实战与进阶&quot;">​</a></h3><p>动手做项目，跟上大模型浪潮。</p><ul><li><strong>框架</strong>：HuggingFace Transformers、LangChain</li><li><strong>任务实战</strong>：情感分析、NER、问答系统</li><li><strong>大模型</strong>：Prompt、RAG、Fine-tuning、Agent</li><li><strong>本站配套</strong>：<a href="./../LLM/Agent/">LLM / Agent</a></li></ul><hr><h2 id="🛠️-工具清单" tabindex="-1">🛠️ 工具清单 <a class="header-anchor" href="#🛠️-工具清单" aria-label="Permalink to &quot;🛠️ 工具清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><strong>HuggingFace</strong></td><td>预训练模型与数据集的集散地</td></tr><tr><td><strong>PyTorch</strong></td><td>深度学习框架（<a href="./../PyTorch/">入门</a>）</td></tr><tr><td><strong>spaCy / jieba</strong></td><td>分词、实体识别（工程用）</td></tr><tr><td><strong>LangChain</strong></td><td>LLM 应用编排</td></tr></tbody></table><hr><h2 id="💡-学习建议" tabindex="-1">💡 学习建议 <a class="header-anchor" href="#💡-学习建议" aria-label="Permalink to &quot;💡 学习建议&quot;">​</a></h2><ol><li><strong>先跑通再深究</strong>：用 HuggingFace 跑一个情感分析，比读十篇论文更有体感</li><li><strong>抓住主线</strong>：任何新模型，先问&quot;它在 Transformer 基础上改了什么&quot;</li><li><strong>跟上大模型</strong>：传统 NLP 任务大多可被大模型 + 提示词解决，不必死磕老方法</li><li><strong>动手写</strong>：本站 <a href="./4.与深度学习的关系.html">与深度学习的关系</a> 里的代码都可以直接跑</li></ol><hr><h2 id="🎯-小结" tabindex="-1">🎯 小结 <a class="header-anchor" href="#🎯-小结" aria-label="Permalink to &quot;🎯 小结&quot;">​</a></h2><ul><li>学习主线：词向量 → 序列模型 → Transformer → 预训练 → 大模型</li><li>Transformer 是核心，值得花最多时间</li><li>用 HuggingFace 动手实践，效率最高</li></ul><hr>`,35)])])}const u=r(l,[["render",i]]);export{c as __pageData,u as default};
